      renwu = "npc",
      role1 = 211000,
      role2 = 201105,
      role3 = 201204,
      role5 = 211404,
      roleanim = 1.2,
      sentence = "I don't know why you feel so hurt, or why you think my expectations are so important.",
      voice = 2,
