      renwu = "npc",
      role1 = 211000,
      role2 = 201105,
      role3 = 201204,
      role5 = 211404,
      roleanim = 1.2,
      sentence = "I hope that with me, you can feel less pressure to grow. I think you're great, and I can even accept any and all of your failings.",
