      role1 = 211000,
      role2 = 201104,
      role3 = 201201,
      role5 = 211404,
      roleanim = 1.2,
      sentence = "Maybe it's because I know that even when you doubt yourself, you still keep moving forward. When you stumble, you pick yourself back up. When you fail, you find of a way to succeed.",
