      renwu = "npc",
      role1 = 211000,
      role2 = 201104,
      role3 = 201201,
      role5 = 211404,
      roleanim = 1.2,
      sentence = "I believe I can sufficiently console you in all your failings, solve all your problems, and give you the companionship you need.",
