      role3 = 402202,
      role5 = 429401,
      sentence = "他平静自然地说着，只是眼睛里，却透出了几分恳切。",
      next = {18}
    },
    [18] = {
      beijing = 2246,
      dialog = 3,
      music = "47_Warm_Daily",
      renwu = "npc",
      role1 = 429000,
      role2 = 402110,
      role3 = 402202,
      role5 = 429401,
      sentence = "我忍不住扑哧一声笑了，随后点点头。",
      next = {19}
    },
    [19] = {
      beijing = 2246,
      dhead = 113,
