  [822600] = {
    [1] = {
      beijing = 1114,
      dialog = 3,
      music = "105_LZY_Silence",
      renwu = "npc",
      sentence = "胧胧烟雨，我和李泽言在曲径小道上相伴而行。",
      next = {2}
    },
    [2] = {
      beijing = 1114,
      dialog = 3,
      music = "105_LZY_Silence",
      renwu = "npc",
      sentence = "他低下头，炽热的气息愈来越近……",
      next = {3}
    },
    [3] = {
      beijing = 1114,
      dialog = 3,
      music = "105_LZY_Silence",
      renwu = "npc",
      sentence = "突然在下个瞬间，李泽言倏地变成了一本巨大的人型空白竞标书，伫立在我面前，对我撅着嘴巴！",
      next = {4}
    },
    [4] = {
      beijing = 1114,
      bganim = 2,
      dhead = 103,
      dialog = 1,
      music = "105_LZY_Silence",
      renming = "$u",
      renwu = "npc",
      sentence = "啊——",
      next = {5}
    },
    [5] = {
      beijing = 2342,
      bganim = 1,
      dialog = 3,
      music = "59_Romantic_Warm",
      renwu = "npc",
      role1 = 191000,
      role2 = 101108,
      role3 = 101201,
      ruchang = -1,
      sentence = "我尖叫着惊醒，下一秒台灯被拧开，照亮了睡眼惺忪的李泽言。",
      next = {6}
    },
    [6] = {
      beijing = 2342,
      dialog = 2,
      idx = 1,
      music = "59_Romantic_Warm",
      renming = "李泽言",
      renwu = "npc",
      role1 = 191000,
      role2 = 101108,
      role3 = 101204,
      sentence = "做噩梦了？",
      next = {7}
    },
    [7] = {
      beijing = 2342,
      dialog = 3,
      music = "59_Romantic_Warm",
      renwu = "npc",
      role1 = 191000,
      role2 = 101108,
      role3 = 101201,
      sentence = "我惊魂未定地拍着胸脯，把刚才的梦语无伦次地告诉了他。",
      next = {8}
    },
    [8] = {
      beijing = 2342,
      dialog = 2,
      idx = 1,
      music = "59_Romantic_Warm",
      renming = "李泽言",
      renwu = "npc",
      role1 = 191000,
      role2 = 101104,
      role3 = 101201,
      sentence = "……看来$c最近的竞标项目压力有点大。",
      next = {9}
    },
    [9] = {
      beijing = 2342,
      dhead = 106,
      dialog = 1,
      music = "59_Romantic_Warm",
      renming = "$u",
      renwu = "npc",
      role1 = 191000,
      role2 = 101104,
      role3 = 101201,
      ruchang = 9,
      sentence = "应该是吧……",
      next = {10}
    },
    [10] = {
      beijing = 2342,
      dialog = 3,
      music = "59_Romantic_Warm",
      renwu = "npc",
      sentence = "这段时间，$c正在竞标市政府的大型传统文化活动，旨在年轻群体中大力宣传传统文化。",
      next = {11}
    },
    [11] = {
      beijing = 2342,
      dialog = 3,
      music = "59_Romantic_Warm",
      renwu = "npc",
      sentence = "考虑到它的意义，我便想做一个足够有价值的活动。",
      next = {12}
    },
    [12] = {
      beijing = 2342,
      dialog = 3,
      music = "59_Romantic_Warm",
      renwu = "npc",
      sentence = "但眼看竞标下个月就要开始了，我却迟迟没有灵感……",
      next = {13}
    },
    [13] = {
      beijing = 2342,
      dialog = 2,
      idx = 1,
      music = "59_Romantic_Warm",
      renming = "李泽言",
      renwu = "npc",
      role1 = 191000,
      role2 = 101103,
      role3 = 101202,
      ruchang = -1,
      sentence = "认真做事是好事。",
      next = {14}
    },
    [14] = {
      beijing = 2342,
      dialog = 2,
      idx = 1,
      music = "59_Romantic_Warm",
      renming = "李泽言",
      renwu = "npc",
      role1 = 191000,
      role2 = 101103,
      role3 = 101202,
      sentence = "但一味去钻牛角尖，一切就本末倒置了。",
      next = {15}
    },
    [15] = {
      beijing = 2342,
      dialog = 3,
      music = "59_Romantic_Warm",
      renwu = "npc",
      role1 = 191000,
      role2 = 101103,
      role3 = 101202,
      roleanim = 1.1,
      sentence = "见我一脸愁容，李泽言伸手将我额前的碎发理好。",
      next = {16}
    },
    [16] = {
      beijing = 2342,
      dialog = 2,
      idx = 1,
      music = "59_Romantic_Warm",
      renming = "李泽言",
      renwu = "npc",
      role1 = 191000,
      role2 = 101103,
      role3 = 101202,
